`timescale 1ns/1ps
// Component fixture generated by the real FAME transform. Original vendor
// clocks and an uninstrumented compiler sibling provide independent oracles.
module fame_clock_progress_tb;
  import "DPI-C" function void checkpoint_widget_failed();
  reg hostClock=0, hostReset=1;
  reg model_clocks_sink_valid=0, model_clocks_sink_bits_A=0, model_clocks_sink_bits_B=0;
  reg model_data_sink_valid=0;
  reg [7:0] model_data_sink_bits=0;
  reg model_value_source_ready=0, model_slow_source_ready=0;
  wire model_clocks_sink_ready, model_data_sink_ready;
  wire model_value_source_valid, model_slow_source_valid;
  wire [7:0] model_value_source_bits, model_slow_source_bits;
  wire ref_clock_ready, ref_data_ready, ref_value_valid, ref_slow_valid;
  wire [7:0] ref_value, ref_slow;
  Top dut(.*);
  ReferenceTop original(.hostClock(hostClock), .hostReset(hostReset),
    .model_clocks_sink_valid(model_clocks_sink_valid), .model_clocks_sink_bits_A(model_clocks_sink_bits_A),
    .model_clocks_sink_bits_B(model_clocks_sink_bits_B), .model_clocks_sink_ready(ref_clock_ready),
    .model_data_sink_valid(model_data_sink_valid), .model_data_sink_bits(model_data_sink_bits),
    .model_data_sink_ready(ref_data_ready), .model_value_source_ready(model_value_source_ready),
    .model_slow_source_ready(model_slow_source_ready), .model_value_source_valid(ref_value_valid),
    .model_slow_source_valid(ref_slow_valid), .model_value_source_bits(ref_value), .model_slow_source_bits(ref_slow));
  integer checks=0, ack=0, stalls=0, step_index=0, overflow_index=-1;
  integer actual_edges_a=0, actual_edges_b=0;
  reg [63:0] consumed_a=0, consumed_b=0, applied_a=0, applied_b=0, steps=0;
  reg pending_a=0, pending_b=0;
  reg [7:0] state_a=0, state_b=0;
  reg sample_tick=0;
  bit corrupt=0;
  bit clock_accepted=0, data_accepted=0;
  always @(posedge dut.model_.clockA_buffer.O) if (!hostReset) actual_edges_a++;
  always @(posedge dut.model_.clockB_buffer.O) if (!hostReset) actual_edges_b++;
  task check(input bit condition, input string reason);
    checks++;
    if (!condition) begin
      $display("FAME_PROGRESS_DIVERGENCE host_step=%0d acknowledged=%0d signal=%s",step_index,ack,reason);
      checkpoint_widget_failed(); $finish;
    end
  endtask
  task compare;
    check(dut.model_.checkpoint_fame_completed_steps===steps,"completed_steps");
    check(dut.model_.checkpoint_fame_clockA_consumed===consumed_a,"clockA_consumed");
    check(dut.model_.checkpoint_fame_clockB_consumed===consumed_b,"clockB_consumed");
    check(dut.model_.checkpoint_fame_clockA_applied===applied_a,"clockA_applied");
    check(dut.model_.checkpoint_fame_clockB_applied===applied_b,"clockB_applied");
    check(dut.model_.checkpoint_fame_clockA_pending===pending_a,"clockA_pending");
    check(dut.model_.checkpoint_fame_clockB_pending===pending_b,"clockB_pending");
    check(!dut.model_.checkpoint_fame_overflow,"no healthy overflow");
    check(actual_edges_a==applied_a && actual_edges_b==applied_b,"independent actual native clock edges");
    check(dut.model_.a===state_a && dut.model_.b===state_b,"independent original state arithmetic");
    check(dut.model_.a===original.model_.a && dut.model_.b===original.model_.b,"uninstrumented original state");
    check({model_clocks_sink_ready,model_data_sink_ready,model_value_source_valid,model_slow_source_valid,
      model_value_source_bits,model_slow_source_bits}===
      {ref_clock_ready,ref_data_ready,ref_value_valid,ref_slow_valid,ref_value,ref_slow},"all original boundary outputs");
    check(consumed_a==applied_a+pending_a && consumed_b==applied_b+pending_b,"one-token lookahead identity");
  endtask
  task step;
    hostClock=0; #3;
    clock_accepted=model_clocks_sink_valid && model_clocks_sink_ready;
    data_accepted=model_data_sink_valid && model_data_sink_ready;
    if (hostReset) begin
      steps=0; consumed_a=0; consumed_b=0; applied_a=0; applied_b=0; pending_a=0; pending_b=0;
    end else if (model_clocks_sink_valid && model_clocks_sink_ready) begin
      steps++;
      if (pending_a) begin applied_a++; state_a=state_a+model_data_sink_bits; end
      if (pending_b) begin applied_b++; state_b++; end
      if (model_clocks_sink_bits_A) consumed_a++;
      if (model_clocks_sink_bits_B) consumed_b++;
      pending_a=model_clocks_sink_bits_A; pending_b=model_clocks_sink_bits_B;
    end else stalls++;
    hostClock=1; #3;
    sample_tick=~sample_tick;
  endtask
  initial begin
    $dumpfile("fame-progress.vcd"); $dumpvars(0,fame_clock_progress_tb);
    corrupt=$test$plusargs("corrupt");
    if ($value$plusargs("overflow=%d",overflow_index)) check(overflow_index>=0 && overflow_index<5,"known overflow case");
    // These four assignments initialize COMPONENT reference arithmetic only.
    // They are not checkpoint transport or FPGA-origin capture/restore evidence.
    dut.model_.a=0; dut.model_.b=0; original.model_.a=0; original.model_.b=0;
    #120; // retain vendor startup/GSR timing; no target or host edge yet
    repeat(4) step();
    check(dut.model_.checkpoint_fame_completed_steps==0 && !dut.model_.checkpoint_fame_overflow,"reset zero-edge observer readback");
    hostReset=0;
    for (integer i=0;i<512;i++) begin
      step_index=i+1;
      if (!model_clocks_sink_valid || clock_accepted) begin
        model_clocks_sink_valid=(i%11!=3 && i%11!=4);
        model_clocks_sink_bits_A=(i%4!=1);
        model_clocks_sink_bits_B=(i%3==0);
      end
      if (!model_data_sink_valid || data_accepted) begin
        model_data_sink_valid=(i%7!=2);
        model_data_sink_bits=i*6+2;
      end
      model_value_source_ready=(i%9!=5 && i%9!=6);
      model_slow_source_ready=(i%13!=6);
      step();
      if (corrupt && step_index==17) force dut.model_.checkpoint_fame_clockA_applied=64'd99;
      compare(); ack++;
    end
    check(steps>100 && applied_a>60 && applied_b>30 && stalls>80,"active multi-clock backpressure scope");
    if (overflow_index>=0) begin
      // Reach each otherwise impractical 64-bit wrap boundary independently.
      hostClock=0;
      model_clocks_sink_valid=1;model_data_sink_valid=1;model_value_source_ready=1;model_slow_source_ready=1;
      model_clocks_sink_bits_A=1;model_clocks_sink_bits_B=1;
      // Clear previously-fired channels and prime both pending clock flags.
      repeat(4) step(); hostClock=0; #3;
      case(overflow_index)
        0: dut.model_.checkpoint_fame_completed_steps=64'hffffffffffffffff;
        1: dut.model_.checkpoint_fame_clockA_consumed=64'hffffffffffffffff;
        2: dut.model_.checkpoint_fame_clockA_applied=64'hffffffffffffffff;
        3: dut.model_.checkpoint_fame_clockB_consumed=64'hffffffffffffffff;
        4: dut.model_.checkpoint_fame_clockB_applied=64'hffffffffffffffff;
      endcase
      step();
      check(dut.model_.checkpoint_fame_overflow,"sticky overflow detects every counter");
      case(overflow_index)
        0: check(dut.model_.checkpoint_fame_completed_steps==64'hffffffffffffffff,"steps saturate");
        1: check(dut.model_.checkpoint_fame_clockA_consumed==64'hffffffffffffffff,"A consumed saturates");
        2: check(dut.model_.checkpoint_fame_clockA_applied==64'hffffffffffffffff,"A applied saturates");
        3: check(dut.model_.checkpoint_fame_clockB_consumed==64'hffffffffffffffff,"B consumed saturates");
        4: check(dut.model_.checkpoint_fame_clockB_applied==64'hffffffffffffffff,"B applied saturates");
      endcase
      model_clocks_sink_valid=0;repeat(5)step();check(dut.model_.checkpoint_fame_overflow,"stall cannot clear overflow");
      hostReset=1;step();check(!dut.model_.checkpoint_fame_overflow && dut.model_.checkpoint_fame_completed_steps==0,"explicit observer reset");
    end
    $display("FAME_PROGRESS_PASS checks=%0d cycles=512 steps=%0d stalls=%0d overflow_case=%0d",checks,steps,stalls,overflow_index);
    $finish;
  end
endmodule
